By default, SAS writes its output to a text file (a "listing" or "lst") file.
I modified the eng_interpreted function to read the SAS output.
The updated function will only grab the listing file, not graphics or any other output.
The updated function will not grab any errors or warnings from the log file.
The listing and log files are automatically deleted.

---

```
eng_interpreted = function(options) {
  if(options$engine == 'sas'){
    sastemp = basename(tempfile(options$engine))
    f = paste(sastemp,"sas",sep=".")
    saslst = paste(sastemp,"lst",sep=".")
    saslog = paste(sastemp,"log",sep=".")
    writeLines(options$code, f)
    on.exit(unlink(c(f,saslst,saslog)))
    code = f
  } else if (options$engine %in% c('highlight', 'Rscript')) {
    f = basename(tempfile(options$engine, '.', '.txt'))
    writeLines(options$code, f)
    on.exit(unlink(f))
    code = f
  } else if (options$engine %in% c('haskell')) {
    # need multiple -e because the engine does not accept \n in code
    code = paste('-e', shQuote(options$code), collapse = ' ')
  } else code = paste(switch(
    options$engine, bash = '-c', coffee = '-p -e', perl = '-e', python = '-c',
    ruby = '-e', sh = '-c', zsh = '-c', NULL
  ), shQuote(str_c(options$code, collapse = '\n')))
  # FIXME: for these engines, the correct order is options + code + file
  code = if (options$engine %in% c('awk', 'gawk', 'sed','sas'))
    paste(code, options$engine.opts) else paste(options$engine.opts, code)
  cmd = paste(shQuote(options$engine.path %n% options$engine), code)
  message('running: ', cmd)
  out = if (options$eval) system(cmd, intern = TRUE) else ''
  if(options$eval & options$engine == 'sas' & file.exists(saslst)) out = c(readLines(saslst),out)
  engine_output(options, options$code, out)
} 
```

